  var momentWords = (event) => Object.values(event?.text || {}).join(" ").toLowerCase();
  var hashText = (text) => {
    let value = 2166136261;
    for (const char of text) value = Math.imul(value ^ char.codePointAt(0), 16777619) >>> 0;
    return value;
  };
  function describeHighlight(event, life) {
    const words = momentWords(event);
    const type = event?.type || "";
    let scene = life?.urban ? "city" : "field", motif = "memory";
    if (type === "birth") {
      scene = "hospital";
      motif = "baby";
    } else if (/地震|洪水|台风|颱風|earthquake|flood|typhoon/.test(words)) {
      motif = "storm";
    } else if (/病|诊|診|医生|醫生|医院|醫院|健康|treatment|hospital|doctor|illness|health/.test(words) || ["health", "death"].includes(type)) {
      scene = "hospital";
      motif = "health";
    } else if (/生日|birthday/.test(words)) {
      scene = "birthday";
      motif = "cake";
    } else if (/拍照|照片|摄影|攝影|photo|camera/.test(words)) {
      scene = "home";
      motif = "camera";
    } else if (/画画|繪畫|绘画|painting|drawing/.test(words)) {
      scene = "home";
      motif = "paint";
    } else if (/毕业|畢業|考试|考試|学校|學校|大学|大學|学位|學位|入学|入學|graduat|exam|school|college|university|degree/.test(words) || type === "education") {
      scene = "school";
      motif = /毕业|畢業|学位|學位|graduat|degree/.test(words) ? "graduate" : "book";
    } else if (/结婚|結婚|婚礼|婚禮|married|wedding/.test(words)) {
      scene = "home";
      motif = "wedding";
    } else if (/出生了|孩子|小生命|child|baby|grandparent/.test(words) || type === "family") {
      scene = "home";
      motif = "baby";
    } else if (/交往|伴侣|伴侶|恋|戀|love|relationship|partner/.test(words) || type === "love") {
      scene = "home";
      motif = "heart";
    } else if (/汽车|汽車|车辆|車輛|car|vehicle/.test(words)) {
      scene = "city";
      motif = "car";
    } else if (/买房|買房|住房|房产|房產|新家|house|housing|home purchase/.test(words)) {
      scene = "home";
      motif = "house";
    } else if (/投资|投資|存款|股票|基金|债券|債券|现金|現金|investment|stock|fund|bond|cash/.test(words) || ["asset", "money"].includes(type)) {
      scene = "office";
      motif = "coin";
    } else if (/搬到|搬家|迁|遷|旅|move|relocat|travel/.test(words) || type === "move") {
      motif = "suitcase";
    } else if (/工作|职业|職業|公务|公務|企业|企業|退休|job|work|career|retir/.test(words) || ["career", "work"].includes(type)) {
      scene = "office";
      motif = "work";
    } else if (/公园|公園|散步|朋友|邻居|鄰居|运动|運動|读书|讀書|park|walk|friend|neighbor|sport|read/.test(words) || type === "warm") {
      scene = "park";
      motif = "sun";
    }
    const sequence = Number(event?.id?.match(/-(\d+)$/)?.[1]);
    return { scene, motif, variant: Number.isSafeInteger(sequence) ? sequence : hashText(`${event?.id || ""}|${words}`) };
  }
  function drawMotif(p, motif) {
    const x = 52, y = 15;
    if (motif === "baby") {
      p.px(x, y + 4, 8, 5, PAL.bedWhite);
      p.px(x + 2, y + 2, 4, 4, PAL.skin);
      p.px(x + 1, y + 8, 6, 2, PAL.pink);
    } else if (motif === "heart" || motif === "wedding") {
      p.px(x + 1, y + 2, 2, 2, PAL.heart);
      p.px(x + 5, y + 2, 2, 2, PAL.heart);
      p.px(x + 1, y + 4, 6, 2, PAL.heart);
      p.px(x + 2, y + 6, 4, 2, PAL.heart);
      p.px(x + 3, y + 8, 2, 2, PAL.heart);
      if (motif === "wedding") p.px(x + 1, y + 11, 6, 1, PAL.sun);
    } else if (motif === "book" || motif === "graduate") {
      p.px(x, y + 4, 8, 7, "#f7eee0");
      p.px(x + 3.5, y + 4, 1, 7, PAL.cityDark);
      p.px(x + 1, y + 5, 2, 1, PAL.cityBlue);
      p.px(x + 5, y + 5, 2, 1, PAL.cityBlue);
      if (motif === "graduate") {
        p.px(x - 1, y + 1, 10, 2, PAL.hair);
        p.px(x + 2, y, 4, 1, PAL.hair);
      }
    } else if (motif === "car") {
      p.px(x, y + 5, 9, 4, PAL.roofTeal);
      p.px(x + 2, y + 3, 5, 2, PAL.sky);
      p.px(x + 1, y + 9, 2, 2, PAL.hair);
      p.px(x + 6, y + 9, 2, 2, PAL.hair);
    } else if (motif === "house") {
      p.px(x + 1, y + 5, 8, 7, PAL.bedWhite);
      p.px(x, y + 3, 10, 2, PAL.roofRed);
      p.px(x + 4, y + 8, 2, 4, PAL.wallDark);
    } else if (motif === "coin") {
      p.px(x + 1, y + 2, 7, 9, PAL.sun);
      p.px(x + 3, y + 4, 3, 5, "#a8875f");
    } else if (motif === "health") {
      p.px(x + 3, y + 2, 3, 10, PAL.red);
      p.px(x, y + 5, 9, 3, PAL.red);
    } else if (motif === "suitcase" || motif === "work") {
      p.px(x + 1, y + 5, 8, 7, PAL.wallDark);
      p.px(x + 3, y + 3, 4, 2, PAL.wallDark);
      p.px(x + 2, y + 7, 6, 1, PAL.floor);
    } else if (motif === "storm") {
      p.px(x, y + 1, 8, 3, PAL.cityDark);
      p.px(x + 2, y + 5, 2, 4, PAL.sun);
      p.px(x + 4, y + 7, 2, 4, PAL.sun);
    } else if (motif === "cake") {
      p.px(x + 1, y + 6, 8, 5, PAL.bedWhite);
      p.px(x + 2, y + 4, 6, 2, PAL.pink);
      p.px(x + 4, y + 1, 1, 3, PAL.sun);
    } else if (motif === "camera") {
      p.px(x, y + 4, 10, 7, PAL.cityDark);
      p.px(x + 2, y + 2, 4, 2, PAL.cityDark);
      p.px(x + 4, y + 6, 3, 3, PAL.sky);
    } else if (motif === "paint") {
      p.px(x, y + 2, 9, 9, PAL.bedWhite);
      p.px(x + 2, y + 4, 2, 2, PAL.red);
      p.px(x + 5, y + 4, 2, 2, PAL.sun);
      p.px(x + 3, y + 7, 2, 2, PAL.roofTeal);
    } else {
      p.px(x + 2, y + 2, 5, 5, PAL.sun);
    }
  }
  function drawHighlightScene(canvas, event, life) {
    if (!canvas) return;
    const context = canvas.getContext("2d");
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.imageSmoothingEnabled = false;
    const p = makePainter(context, canvas.width, canvas.height);
    const { scene, motif, variant } = describeHighlight(event, life);
    scenes[scene](p);
    drawMotif(p, motif);
    const colors = ["#d96c6c", "#f2c14e", "#7fb069", "#7fa8c9"];
    for (let tile = 0; tile < 6; tile++) p.px(2 + tile * 2, 2, 1.6, 1.6, colors[Math.floor(variant / 4 ** tile) % 4]);
    p.person(39 + variant % 3 * 3, 24, colors[Math.floor(variant / 7) % 4]);
  }

  // app/life-moments.js
  function selectLifeMoments(life) {
    const log2 = Array.isArray(life?.log) ? life.log : [];
    const byId = new Map(log2.map((event) => [event.id, event]));
    const saved = [...new Set(life?.stars || [])].map((id) => byId.get(id)).filter(Boolean);
    const savedIds = new Set(saved.map((event) => event.id));
    const candidates = log2.filter((event) => ["birth", "education", "love", "family", "career", "move", "work", "asset", "decision", "warm"].includes(event.type));
    const score = (event) => {
      const words = event.text?.zhCN || "";
      let value = { birth: 100, education: 24, love: 21, family: 18, career: 22, move: 15, work: 17, decision: 13, warm: 3, asset: 1 }[event.type] || 0;
      if (/毕业|出生了|结婚|退休|搬到|开始了|获得|取得|购置|安排了/.test(words)) value += 35;
      if (/未能|困难|失去|失败|减少|估值/.test(words)) value -= 30;
      return value + event.age * 2e-3;
    };
    const chosen = [...saved];
    const sameRecord = (left, right) => left.id === right.id || left.age === right.age && left.text?.zhCN && left.text.zhCN === right.text?.zhCN;
    for (let decade = 0; decade <= Math.floor((life?.age || 0) / 10); decade++) {
      const inDecade = chosen.filter((event) => Math.floor(event.age / 10) === decade);
      const ranked = candidates.filter((event) => Math.floor(event.age / 10) === decade && !savedIds.has(event.id)).sort((a, b) => score(b) - score(a));
      for (const event of ranked) {
        if (inDecade.length >= 2) break;
        if (chosen.some((item) => sameRecord(item, event))) continue;
        if (inDecade.length && Math.abs(event.age - inDecade[0].age) < 2) continue;
        if (inDecade.length && score(event) < 48) continue;
        chosen.push(event);
        inDecade.push(event);
      }
    }
    return chosen.sort((a, b) => a.age - b.age || a.year - b.year || a.id.localeCompare(b.id));
  }

