  // app/family-model.js
  function siblingWeights(year, urban, region = "mainland") {
    if (region !== "mainland") return year < 1975 ? [0.16, 0.23, 0.25, 0.2, 0.11, 0.05] : year < 2e3 ? [0.3, 0.36, 0.23, 0.09, 0.02] : [0.48, 0.34, 0.14, 0.04];
    if (year <= 1970) return [0.1, 0.18, 0.24, 0.22, 0.16, 0.1];
    if (year <= 1979) return [0.14, 0.24, 0.28, 0.2, 0.1, 0.04];
    if (year <= 2015) return urban ? [0.55, 0.19, 0.15, 0.08, 0.03] : [0.42, 0.25, 0.14, 0.1, 0.06, 0.03];
    if (year <= 2020) return [0.3, 0.36, 0.23, 0.09, 0.02];
    return [0.37, 0.3, 0.24, 0.09];
  }
