  var idealMarriageAge = (year) => 20 + Math.max(0, Math.min(9, (year - 1950) / 76 * 9));
  function fecundity(age) {
    return age < 18 ? 0 : age < 20 ? 0.55 : age < 25 ? 1 : age < 30 ? 0.92 : age < 35 ? 0.68 : age < 40 ? 0.3 : age < 45 ? 0.04 : age < 50 ? 6e-3 : 0;
  }
  function canConceive(life) {
    const partner = life.family.partner;
    if (!partner?.alive || !partner.married || !Number.isFinite(partner.sinceYear) || partner.sinceYear >= life.year) return false;
    const age = life.sex === "female" ? life.age : partner.age;
    return fecundity(age) > 0;
  }

